func payloadHash(raw []byte) string {
	h := sha256.Sum256(raw)
	return hex.EncodeToString(h[:])
}

// runIdempotent wraps a mutating operation with idempotency-key handling.
func (s *Service) runIdempotent(c *opCtx, op string, required bool, fn func() (int, interface{}, *ApiError)) (int, interface{}, *ApiError) {
	key, _ := optStr(c.body, "idempotencyKey")
	if key == "" {
		if required {
			return 0, nil, apiErr(400, "idempotency_required", "idempotencyKey is required for this operation")
		}
		return fn()
	}
	fullKey := op + ":" + c.user.ID + ":" + key
	if rec := s.state.Idempotency[fullKey]; rec != nil {
		if rec.PayloadHash != payloadHash(c.raw) {
			return 0, nil, apiErr(409, "idempotency_conflict", "idempotency key was already used with a different payload")
		}
		var stored interface{}
		if err := json.Unmarshal(rec.Response, &stored); err != nil {
			return 0, nil, apiErr(500, "internal_error", "failed to replay stored response")
		}
		return rec.StatusCode, stored, nil
	}
	status, resp, aerr := fn()
	if aerr != nil {
		return 0, nil, aerr
	}
	raw, err := json.Marshal(resp)
	if err != nil {
		return 0, nil, apiErr(500, "internal_error", "failed to encode response")
	}
	s.state.Idempotency[fullKey] = &IdemRecord{
		Key: key, Op: op, UserID: c.user.ID, PayloadHash: payloadHash(c.raw),
		StatusCode: status, Response: raw, CreatedAt: time.Now().UTC(),
	}
	return status, resp, nil
}

