func (s *Service) canSeeSample(user *User, role string, sample *Sample) bool {
	switch role {
	case RoleAdministrator, RoleDispatcher:
		return true
	case RoleRequester:
		return sample.RequesterID == user.ID
	case RoleCollectionPro, RoleDeliveryPartner, RoleNodeHandler, RoleLaboratoryTeam:
		if sample.CurrentHolderID == user.ID {
			return true
		}
		for _, a := range s.state.Assignments {
			if a.SampleID == sample.ID && (a.AcceptedWorkerID == user.ID || a.OfferedToWorkerID == user.ID) {
				return true
			}
		}
	}
	return false
}

