func (s *Service) hAcceptAssignment(c *opCtx) (int, interface{}, *ApiError) {
	if err := c.requireRole(RoleCollectionPro, RoleDeliveryPartner, RoleNodeHandler, RoleLaboratoryTeam); err != nil {
		return 0, nil, err
	}
	if err := checkFields(c.body, "assignmentId", "idempotencyKey"); err != nil {
		return 0, nil, err
	}
	return s.runIdempotent(c, "accept_assignment", true, func() (int, interface{}, *ApiError) {
		asgID, err := reqStr(c.body, "assignmentId")
		if err != nil {
			return 0, nil, err
		}
		a := s.state.Assignments[asgID]
		if a == nil {
			return 0, nil, apiErr(404, "not_found", "assignment not found")
		}
		if a.Status == AsgCancelled || a.Status == AsgCompleted {
			return 0, nil, apiErr(409, "assignment_inactive", "assignment is no longer active")
		}
		if a.Status == AsgAccepted || a.Status == AsgInProgress {
			if a.AcceptedWorkerID == c.user.ID {
				return 201, J{"assignmentId": a.ID, "workerId": c.user.ID, "status": "accepted"}, nil
			}
			return 0, nil, apiErr(409, "assignment_taken", "assignment was already accepted by another worker")
		}
		if a.Status != AsgOffered || a.OfferedToWorkerID != c.user.ID {
			return 0, nil, apiErr(409, "offer_not_available", "assignment is not currently offered to you")
		}
		if a.OfferExpiresAt != nil && a.OfferExpiresAt.Before(time.Now().UTC()) {
			return 0, nil, apiErr(409, "offer_not_available", "offer has expired")
		}
		if kindRole(a.Kind) != c.sess.ActiveRole {
			return 0, nil, apiErr(403, "ineligible_worker", "your active role cannot accept this assignment")
		}
		if !c.user.Available {
			return 0, nil, apiErr(409, "worker_unavailable", "worker is not available")
		}
		if c.user.CapacityUnits >= 0 && s.activeAssignmentCount(c.user.ID) >= c.user.CapacityUnits {
			return 0, nil, apiErr(409, "capacity_exhausted", "worker capacity exhausted")
		}
		now := time.Now().UTC()
		a.Status = AsgAccepted
		a.AcceptedWorkerID = c.user.ID
		a.AcceptedAt = &now
		c.user.AssignmentCount++
		c.audit("accept_assignment", "assignment", a.ID, a.SampleID, true, map[string]interface{}{
			"kind": a.Kind, "journeyId": a.JourneyID,
		})
		s.emit("assignment.accepted", "assignment", a.ID, map[string]interface{}{
			"assignmentId": a.ID, "workerId": c.user.ID, "sampleId": a.SampleID,
		})
		return 201, J{"assignmentId": a.ID, "workerId": c.user.ID, "status": "accepted"}, nil
	})
}

