func (s *Service) hCollectAndSeal(c *opCtx) (int, interface{}, *ApiError) {
	if err := c.requireRole(RoleCollectionPro); err != nil {
		return 0, nil, err
	}
	if err := checkFields(c.body, "sampleId", "containerType", "collectedAt", "idempotencyKey"); err != nil {
		return 0, nil, err
	}
	return s.runIdempotent(c, "collect_and_seal_sample", true, func() (int, interface{}, *ApiError) {
		sampleID, err := reqStr(c.body, "sampleId")
		if err != nil {
			return 0, nil, err
		}
		containerType, err := reqStr(c.body, "containerType")
		if err != nil {
			return 0, nil, err
		}
		collectedAt, aerr := reqTimeField(c.body, "collectedAt")
		if aerr != nil {
			return 0, nil, aerr
		}
		sample := s.state.Samples[sampleID]
		if sample == nil {
			return 0, nil, apiErr(404, "not_found", "sample not found")
		}
		if sample.Sealed {
			return 0, nil, apiErr(409, "already_sealed", "sample is already sealed")
		}
		if sample.Status == SampleCancelled || sample.Status == SampleExpired || sample.Status == SampleReceived {
			return 0, nil, apiErr(409, "invalid_sample_state", "sample is in a terminal state")
		}
		// caller must hold the collection assignment for this sample
		var collAsg *Assignment
		for _, a := range s.state.Assignments {
			if a.SampleID == sample.ID && a.Kind == KindCollection &&
				(a.Status == AsgAccepted || a.Status == AsgInProgress) && a.AcceptedWorkerID == c.user.ID {
				collAsg = a
				break
			}
		}
		if collAsg == nil {
			return 0, nil, apiErr(403, "forbidden", "you do not hold the collection assignment for this sample")
		}
		st := s.state.SampleTypes[sample.SampleTypeID]
		if st != nil && st.QualifiedCollectorRequired && !c.user.HasQualification(st.RequiredQualification) {
			return 0, nil, apiErr(403, "missing_qualification", "you lack the qualification required to collect this sample type")
		}
		if collectedAt.Before(sample.EarliestCollectionAt) || collectedAt.After(sample.LatestCollectionAt) {
			return 0, nil, apiErr(409, "outside_collection_window", "collection time is outside the collection window")
		}
		compliant := containerType == sample.ContainerType
		now := time.Now().UTC()
		sample.Sealed = true
		sample.SealedAt = &collectedAt
		sample.Status = SampleSealed
		sample.CurrentHolderID = c.user.ID
		loc := s.state.Locations[sample.OriginLocationID]
		if loc != nil {
			co := loc.Coordinate
			sample.LatestLocation = &co
			sample.LocationRecordedAt = &now
		}
		collAsg.Status = AsgCompleted
		collAsg.CompletedAt = &collectedAt
		if j := s.state.Journeys[sample.ActiveJourneyID]; j != nil {
			j.Status = JourneyInProgress
			for _, stop := range j.Stops {
				if stop.StopType == "pickup" && stop.CompletedAt == nil {
					stop.CompletedAt = &collectedAt
				}
			}
		}
		c.audit("collect_and_seal_sample", "sample", sample.ID, sample.ID, true, map[string]interface{}{
			"collectedAt": fmtTime(collectedAt), "containerType": containerType, "handlingCompliant": compliant,
		})
		s.emit("sample.sealed", "sample", sample.ID, map[string]interface{}{
			"sampleId": sample.ID, "holderId": c.user.ID,
		})
		return 201, J{
			"sampleId": sample.ID, "status": "sealed", "sealedAt": fmtTime(collectedAt),
			"handlingCompliant": compliant,
		}, nil
	})
}

func (s *Service) hRecordWorkerLocation(c *opCtx) (int, interface{}, *ApiError) {
	if err := c.requireRole(RoleCollectionPro, RoleDeliveryPartner); err != nil {
		return 0, nil, err
	}
	if err := checkFields(c.body, "assignmentId", "coordinate", "sequence", "recordedAt", "idempotencyKey"); err != nil {
		return 0, nil, err
	}
	return s.runIdempotent(c, "record_worker_location", true, func() (int, interface{}, *ApiError) {
		asgID, err := reqStr(c.body, "assignmentId")
		if err != nil {
			return 0, nil, err
		}
		coord, aerr := reqCoord(c.body, "coordinate", "invalid_coordinate")
		if aerr != nil {
			return 0, nil, aerr
		}
		seq, err := reqInt(c.body, "sequence")
		if err != nil {
			return 0, nil, err
		}
		if seq < 1 {
			return 0, nil, apiErr(400, "invalid_sequence", "sequence must be >= 1")
		}
		recordedAt, aerr := reqTimeField(c.body, "recordedAt")
		if aerr != nil {
			return 0, nil, aerr
		}
		a := s.state.Assignments[asgID]
		if a == nil {
			return 0, nil, apiErr(404, "not_found", "assignment not found")
		}
		if a.AcceptedWorkerID != c.user.ID || (a.Status != AsgAccepted && a.Status != AsgInProgress) {
			return 0, nil, apiErr(409, "assignment_inactive", "assignment is not active for you")
		}
		if seq <= a.LastLocationSeq {
			return 0, nil, apiErr(409, "stale_location", "a newer location was already recorded for this assignment")
		}
		a.LastLocationSeq = seq
		c.user.LatestLocation = &coord
		c.user.LocationRecordedAt = &recordedAt
		if sample := s.state.Samples[a.SampleID]; sample != nil && sample.CurrentHolderID == c.user.ID {
			sample.LatestLocation = &coord
			sample.LocationRecordedAt = &recordedAt
		}
		c.audit("record_worker_location", "assignment", a.ID, a.SampleID, true, map[string]interface{}{
			"latitude": coord.Latitude, "longitude": coord.Longitude, "sequence": seq,
		})
		s.emit("worker.location", "user", c.user.ID, map[string]interface{}{
			"workerId": c.user.ID, "assignmentId": a.ID, "sampleId": a.SampleID,
			"latitude": coord.Latitude, "longitude": coord.Longitude, "recordedAt": fmtTime(recordedAt),
		})
		return 201, J{"recorded": true, "sequence": seq}, nil
	})
}

var transportProgressOrder = []string{"at_pickup", "picked_up", "in_transit", "arrived", "delivered"}

func progressIndex(status string) int {
	for i, x := range transportProgressOrder {
		if x == status {
			return i
		}
	}
	return -1
}

func (s *Service) hUpdateAssignmentProgress(c *opCtx) (int, interface{}, *ApiError) {
	if err := c.requireRole(RoleCollectionPro, RoleDeliveryPartner, RoleNodeHandler, RoleLaboratoryTeam); err != nil {
		return 0, nil, err
	}
	if err := checkFields(c.body, "assignmentId", "status", "occurredAt", "idempotencyKey"); err != nil {
		return 0, nil, err
	}
	return s.runIdempotent(c, "update_assignment_progress", true, func() (int, interface{}, *ApiError) {
		asgID, err := reqStr(c.body, "assignmentId")
		if err != nil {
			return 0, nil, err
		}
		status, err := reqStr(c.body, "status")
		if err != nil {
			return 0, nil, err
		}
		validStatus := progressIndex(status) >= 0 || status == "in_progress" || status == "completed"
		if !validStatus {
			return 0, nil, apiErr(400, "invalid_status", "unknown progress status")
		}
		occurredAt, aerr := reqTimeField(c.body, "occurredAt")
		if aerr != nil {
			return 0, nil, aerr
		}
		a := s.state.Assignments[asgID]
		if a == nil {
			return 0, nil, apiErr(404, "not_found", "assignment not found")
		}
		if a.Status == AsgCancelled || a.Status == AsgCompleted {
			return 0, nil, apiErr(409, "assignment_inactive", "assignment is no longer active")
		}
		if a.AcceptedWorkerID != c.user.ID {
			return 0, nil, apiErr(403, "ineligible_worker", "you are not the assigned worker")
		}
		sample := s.state.Samples[a.SampleID]
		if a.Kind == KindTransport {
			idx := progressIndex(status)
			if idx < 0 {
				return 0, nil, apiErr(409, "invalid_transition", "invalid progress status for a transport leg")
			}
			lastIdx := -1
			var lastTime time.Time
			for _, p := range a.Progress {
				if pi := progressIndex(p.Status); pi > lastIdx {
					lastIdx = pi
					lastTime = p.OccurredAt
				}
			}
			if idx <= lastIdx {
				return 0, nil, apiErr(409, "invalid_transition", "progress must move forward")
			}
			if !lastTime.IsZero() && occurredAt.Before(lastTime) {
				return 0, nil, apiErr(409, "invalid_progress_time", "occurredAt is before the previous progress update")
			}
			if idx >= 1 { // picked_up and beyond require custody
				if sample == nil || sample.CurrentHolderID != c.user.ID {
					return 0, nil, apiErr(409, "custody_required", "you must hold custody of the sample first")
				}
			}
			if idx >= 1 {
				// prior leg must be complete
				j := s.state.Journeys[a.JourneyID]
				if j != nil {
					for _, legID := range j.LegIDs {
						other := s.state.Assignments[legID]
						if other != nil && other.Sequence < a.Sequence && other.Status != AsgCompleted && other.Status != AsgCancelled {
							return 0, nil, apiErr(409, "prior_leg_incomplete", "a prior transport leg is not complete")
						}
					}
				}
			}
			if status == "delivered" && sample != nil && occurredAt.After(sample.DeliveryDeadline) {
				return 0, nil, apiErr(409, "delivery_deadline_exceeded", "delivery deadline has passed")
			}
		}
		a.Progress = append(a.Progress, ProgressEntry{Status: status, OccurredAt: occurredAt})
		if a.Status == AsgAccepted {
			a.Status = AsgInProgress
		}
		if sample != nil {
			switch status {
			case "picked_up", "in_transit":
				if sample.Status == SampleSealed || sample.Status == SampleAtNode {
					sample.Status = SampleInTransit
				}
			case "arrived", "delivered":
				if a.Kind == KindTransport {
					if loc := s.state.Locations[a.ToLocationID]; loc != nil && loc.HasFunction(LocLaboratory) {
						// stay in_transit until receipt
					} else if sample.Status == SampleInTransit {
						sample.Status = SampleAtNode
					}
				}
			}
		}
		c.audit("update_assignment_progress", "assignment", a.ID, a.SampleID, true, map[string]interface{}{
			"status": status, "occurredAt": fmtTime(occurredAt),
		})
		s.emit("assignment.progress", "assignment", a.ID, map[string]interface{}{
			"assignmentId": a.ID, "status": status, "sampleId": a.SampleID,
		})
		return 201, J{"assignmentId": a.ID, "status": status, "occurredAt": fmtTime(occurredAt)}, nil
	})
}

func (s *Service) hInitiateHandoff(c *opCtx) (int, interface{}, *ApiError) {
	if err := c.requireRole(RoleCollectionPro, RoleDeliveryPartner, RoleNodeHandler, RoleLaboratoryTeam); err != nil {
		return 0, nil, err
	}
	if err := checkFields(c.body, "sampleId", "fromAssignmentId", "toAssignmentId", "receiverId", "initiatedAt", "idempotencyKey"); err != nil {
		return 0, nil, err
	}
	return s.runIdempotent(c, "initiate_handoff", true, func() (int, interface{}, *ApiError) {
		sampleID, err := reqStr(c.body, "sampleId")
		if err != nil {
			return 0, nil, err
		}
		fromID, err := reqStr(c.body, "fromAssignmentId")
		if err != nil {
			return 0, nil, err
		}
		toID, err := reqStr(c.body, "toAssignmentId")
		if err != nil {
			return 0, nil, err
		}
		receiverID, err := reqStr(c.body, "receiverId")
		if err != nil {
			return 0, nil, err
		}
		initiatedAt, aerr := reqTimeField(c.body, "initiatedAt")
		if aerr != nil {
			return 0, nil, aerr
		}
		sample := s.state.Samples[sampleID]
		if sample == nil {
			return 0, nil, apiErr(404, "not_found", "sample not found")
		}
		if sample.Status == SampleReceived || sample.Status == SampleCancelled || sample.Status == SampleExpired {
			return 0, nil, apiErr(409, "invalid_sample_state", "sample is in a terminal state")
		}
		if sample.CurrentHolderID != c.user.ID {
			return 0, nil, apiErr(409, "not_current_holder", "you are not the current holder of this sample")
		}
		if sample.PendingHandoffID != "" {
			return 0, nil, apiErr(409, "pending_handoff_exists", "a handoff is already pending for this sample")
		}
		fromAsg := s.state.Assignments[fromID]
		if fromAsg == nil || fromAsg.SampleID != sampleID {
			return 0, nil, apiErr(403, "sender_assignment_mismatch", "fromAssignmentId is not your assignment for this sample")
		}
		if fromAsg.AcceptedWorkerID != c.user.ID {
			return 0, nil, apiErr(403, "sender_assignment_mismatch", "fromAssignmentId is not your assignment for this sample")
		}
		toAsg := s.state.Assignments[toID]
		if toAsg == nil || toAsg.SampleID != sampleID {
			return 0, nil, apiErr(409, "receiver_assignment_mismatch", "toAssignmentId is not an assignment for this sample")
		}
		if toAsg.Status != AsgAccepted && toAsg.Status != AsgInProgress {
			return 0, nil, apiErr(409, "offer_not_available", "the receiving assignment has not been accepted")
		}
		if toAsg.AcceptedWorkerID != receiverID {
			return 0, nil, apiErr(409, "receiver_assignment_mismatch", "receiverId does not match the receiving assignment worker")
		}
		receiver := s.state.Users[receiverID]
		if receiver == nil || !receiver.Active {
			return 0, nil, apiErr(409, "receiver_assignment_mismatch", "receiver is not an active worker")
		}
		expected := s.nextAssignmentForHandoff(sample, fromAsg)
		if expected == nil || expected.ID != toAsg.ID {
			return 0, nil, apiErr(409, "nonadjacent_handoff", "the receiving assignment is not the next step in the journey")
		}
		if fromAsg.Kind == KindTransport {
			arrived := false
			for _, p := range fromAsg.Progress {
				if p.Status == "arrived" || p.Status == "delivered" {
					arrived = true
				}
			}
			if !arrived {
				return 0, nil, apiErr(409, "transport_leg_incomplete", "the transport leg has not arrived at its destination")
			}
		}
		h := &Handoff{
			ID: newUUID(), SampleID: sampleID, FromAssignmentID: fromID, ToAssignmentID: toID,
			SenderID: c.user.ID, ReceiverID: receiverID, Status: HandoffPending,
			InitiatedAt: initiatedAt,
		}
		s.state.Handoffs[h.ID] = h
		sample.PendingHandoffID = h.ID
		c.audit("initiate_handoff", "handoff", h.ID, sampleID, true, map[string]interface{}{
			"fromAssignmentId": fromID, "toAssignmentId": toID, "receiverId": receiverID,
		})
		s.emit("handoff.initiated", "handoff", h.ID, s.handoffView(h))
		return 201, J{
			"handoffId": h.ID, "status": "pending",
			"senderConfirmed": false, "receiverConfirmed": false,
		}, nil
	})
}

func (s *Service) completeHandoff(h *Handoff, confirmedAt time.Time) {
	sample := s.state.Samples[h.SampleID]
	h.Status = HandoffConfirmed
	h.ConfirmedAt = &confirmedAt
	if sample == nil {
		return
	}
	sample.PendingHandoffID = ""
	sample.CurrentHolderID = h.ReceiverID
	fromAsg := s.state.Assignments[h.FromAssignmentID]
	toAsg := s.state.Assignments[h.ToAssignmentID]
	cooled := sampleRequiresCooled(s, sample)
	if fromAsg != nil && fromAsg.Status != AsgCompleted {
		fromAsg.Status = AsgCompleted
		fromAsg.CompletedAt = &confirmedAt
		switch fromAsg.Kind {
		case KindTransport:
			if fromAsg.ConnectionID != "" {
				if conn := s.state.Connections[fromAsg.ConnectionID]; conn != nil {
					conn.Capacity.Release(cooled)
				}
			}
			sample.CompletedLegIDs = append(sample.CompletedLegIDs, fromAsg.ID)
		case KindNode:
			if loc := s.state.Locations[fromAsg.NodeID]; loc != nil {
				loc.Capacity.Release(cooled)
			}
		}
	}
	if toAsg != nil && toAsg.Status == AsgAccepted {
		toAsg.Status = AsgInProgress
	}
	if j := s.state.Journeys[sample.ActiveJourneyID]; j != nil {
		for _, stop := range j.Stops {
			if stop.CompletedAt != nil {
				continue
			}
			if fromAsg != nil && fromAsg.Kind == KindTransport && stop.LocationID == fromAsg.ToLocationID {
				stop.CompletedAt = &confirmedAt
			}
		}
	}
	if toAsg != nil && toAsg.Kind == KindNode {
		sample.Status = SampleAtNode
	} else if toAsg != nil && toAsg.Kind == KindTransport {
		sample.Status = SampleInTransit
	}
	s.audit("", "", "custody.transferred", "sample", h.SampleID, h.SampleID, true, map[string]interface{}{
		"handoffId": h.ID, "from": h.SenderID, "to": h.ReceiverID, "confirmedAt": fmtTime(confirmedAt),
	})
	s.emit("custody.transferred", "sample", h.SampleID, map[string]interface{}{
		"sampleId": h.SampleID, "handoffId": h.ID, "from": h.SenderID, "to": h.ReceiverID,
	})
}

func (s *Service) hConfirmHandoff(c *opCtx) (int, interface{}, *ApiError) {
	if err := c.requireRole(RoleCollectionPro, RoleDeliveryPartner, RoleNodeHandler, RoleLaboratoryTeam); err != nil {
		return 0, nil, err
	}
	if err := checkFields(c.body, "handoffId", "confirmationSide", "confirmedAt", "idempotencyKey"); err != nil {
		return 0, nil, err
	}
	return s.runIdempotent(c, "confirm_handoff", true, func() (int, interface{}, *ApiError) {
		handoffID, err := reqStr(c.body, "handoffId")
		if err != nil {
			return 0, nil, err
		}
		side, err := reqStr(c.body, "confirmationSide")
		if err != nil {
			return 0, nil, err
		}
		if side != "sender" && side != "receiver" {
			return 0, nil, apiErr(400, "invalid_confirmation_side", "confirmationSide must be sender or receiver")
		}
		confirmedAt, aerr := reqTimeField(c.body, "confirmedAt")
		if aerr != nil {
			return 0, nil, aerr
		}
		h := s.state.Handoffs[handoffID]
		if h == nil {
			return 0, nil, apiErr(404, "not_found", "handoff not found")
		}
		if h.Status != HandoffPending {
			return 0, nil, apiErr(409, "handoff_inactive", "handoff is already confirmed")
		}
		if side == "sender" && h.SenderID != c.user.ID {
			return 0, nil, apiErr(403, "forbidden", "only the sender can confirm the sender side")
		}
		if side == "receiver" && h.ReceiverID != c.user.ID {
			return 0, nil, apiErr(403, "forbidden", "only the receiver can confirm the receiver side")
		}
		// idempotent: re-confirming the same side does not create a duplicate transfer
		if side == "sender" && !h.SenderConfirmed {
			h.SenderConfirmed = true
			h.SenderConfirmedAt = &confirmedAt
		}
		if side == "receiver" && !h.ReceiverConfirmed {
			h.ReceiverConfirmed = true
			h.ReceiverConfirmedAt = &confirmedAt
		}
		if h.SenderConfirmed && h.ReceiverConfirmed && h.Status == HandoffPending {
			s.completeHandoff(h, confirmedAt)
		}
		c.audit("confirm_handoff", "handoff", h.ID, h.SampleID, true, map[string]interface{}{
			"confirmationSide": side, "status": h.Status,
		})
		s.emit("handoff.confirmed", "handoff", h.ID, s.handoffView(h))
		return 201, J{
			"handoffId": h.ID, "status": h.Status,
			"senderConfirmed": h.SenderConfirmed, "receiverConfirmed": h.ReceiverConfirmed,
		}, nil
	})
}

func (s *Service) hRecordHandlingCheckpoint(c *opCtx) (int, interface{}, *ApiError) {
	if err := c.requireRole(RoleCollectionPro, RoleDeliveryPartner, RoleNodeHandler, RoleLaboratoryTeam); err != nil {
		return 0, nil, err
	}
	if err := checkFields(c.body, "sampleId", "assignmentId", "locationId", "containerType", "observedTemperatureC", "recordedAt", "idempotencyKey"); err != nil {
		return 0, nil, err
	}
	return s.runIdempotent(c, "record_handling_checkpoint", true, func() (int, interface{}, *ApiError) {
		sampleID, err := reqStr(c.body, "sampleId")
		if err != nil {
			return 0, nil, err
		}
		asgID, err := reqStr(c.body, "assignmentId")
		if err != nil {
			return 0, nil, err
		}
		containerType, err := reqStr(c.body, "containerType")
		if err != nil {
			return 0, nil, err
		}
		observedTemp, aerr := reqNum(c.body, "observedTemperatureC")
		if aerr != nil {
			return 0, nil, aerr
		}
		recordedAt, aerr := reqTimeField(c.body, "recordedAt")
		if aerr != nil {
			return 0, nil, aerr
		}
		locationID, aerr := optStr(c.body, "locationId")
		if aerr != nil {
			return 0, nil, aerr
		}
		sample := s.state.Samples[sampleID]
		if sample == nil {
			return 0, nil, apiErr(404, "not_found", "sample not found")
		}
		if sample.Status == SampleReceived || sample.Status == SampleCancelled || sample.Status == SampleExpired {
			return 0, nil, apiErr(409, "terminal_sample", "sample is in a terminal state")
		}
		a := s.state.Assignments[asgID]
		if a == nil || a.SampleID != sampleID {
			return 0, nil, apiErr(404, "not_found", "assignment not found for this sample")
		}
		if a.Status == AsgCancelled || a.Status == AsgCompleted {
			return 0, nil, apiErr(409, "assignment_inactive", "assignment is no longer active")
		}
		if sample.CurrentHolderID != c.user.ID {
			return 0, nil, apiErr(403, "forbidden", "only the current holder can record a handling checkpoint")
		}
		compliant := containerType == sample.ContainerType &&
			observedTemp >= sample.TemperatureMinC && observedTemp <= sample.TemperatureMaxC
		if !compliant {
			s.markSampleException(sample, "handling_excursion", "observed container or temperature outside required range", "")
		}
		c.audit("record_handling_checkpoint", "sample", sample.ID, sample.ID, true, map[string]interface{}{
			"containerType": containerType, "observedTemperatureC": observedTemp,
			"compliant": compliant, "locationId": locationID, "recordedAt": fmtTime(recordedAt),
		})
		s.emit("sample.checkpoint", "sample", sample.ID, map[string]interface{}{
			"sampleId": sample.ID, "compliant": compliant,
		})
		status := sample.Status
		return 201, J{"sampleId": sample.ID, "compliant": compliant, "sampleStatus": status}, nil
	})
}

func (s *Service) hConfirmLabReceipt(c *opCtx) (int, interface{}, *ApiError) {
	if err := c.requireRole(RoleLaboratoryTeam); err != nil {
		return 0, nil, err
	}
	if err := checkFields(c.body, "sampleId", "laboratoryId", "receivedAt", "idempotencyKey"); err != nil {
		return 0, nil, err
	}
	return s.runIdempotent(c, "confirm_laboratory_receipt", true, func() (int, interface{}, *ApiError) {
		sampleID, err := reqStr(c.body, "sampleId")
		if err != nil {
			return 0, nil, err
		}
		labID, err := reqStr(c.body, "laboratoryId")
		if err != nil {
			return 0, nil, err
		}
		receivedAt, aerr := reqTimeField(c.body, "receivedAt")
		if aerr != nil {
			return 0, nil, aerr
		}
		sample := s.state.Samples[sampleID]
		if sample == nil {
			return 0, nil, apiErr(404, "not_found", "sample not found")
		}
		lab := s.state.Locations[labID]
		if lab == nil || lab.Implicit || !lab.HasFunction(LocLaboratory) {
			return 0, nil, apiErr(404, "not_found", "laboratory not found")
		}
		if c.user.AssignedLocationID != labID {
			return 0, nil, apiErr(403, "wrong_laboratory_operator", "you are not assigned to this laboratory")
		}
		if !lab.Active {
			return 0, nil, apiErr(409, "laboratory_unavailable", "laboratory is not active")
		}
		if sample.Status == SampleReceived {
			return 0, nil, apiErr(409, "invalid_sample_state", "sample was already received")
		}
		if sample.Status == SampleCancelled || sample.Status == SampleExpired {
			return 0, nil, apiErr(409, "invalid_sample_state", "sample is in a terminal state")
		}
		if receivedAt.After(sample.DeliveryDeadline) {
			return 0, nil, apiErr(409, "delivery_deadline_exceeded", "the delivery deadline has passed")
		}
		if sample.PendingHandoffID != "" {
			return 0, nil, apiErr(409, "pending_handoff_exists", "a handoff is still pending for this sample")
		}
		if sample.CurrentHolderID != c.user.ID {
			return 0, nil, apiErr(409, "custody_conflict", "you do not hold custody of this sample")
		}
		cooled := sampleRequiresCooled(s, sample)
		sample.Status = SampleReceived
		sample.ReceivedLaboratoryID = labID
		lab.Capacity.Release(cooled)
		now := receivedAt
		if j := s.state.Journeys[sample.ActiveJourneyID]; j != nil {
			for _, id := range j.LaboratoryAssignmentIDs {
				if a := s.state.Assignments[id]; a != nil && a.LaboratoryID == labID && a.Status != AsgCompleted {
					a.Status = AsgCompleted
					a.CompletedAt = &now
				}
			}
			for _, stop := range j.Stops {
				if stop.StopType == "delivery" && stop.CompletedAt == nil {
					stop.CompletedAt = &now
				}
			}
			allDone := true
			for _, sid := range j.SampleIDs {
				if other := s.state.Samples[sid]; other != nil && other.Status != SampleReceived &&
					other.Status != SampleCancelled && other.Status != SampleExpired && other.Status != SampleException {
					allDone = false
				}
			}
			if allDone {
				j.Status = JourneyCompleted
				j.CompletedAt = &now
			}
		}
		c.audit("confirm_laboratory_receipt", "sample", sample.ID, sample.ID, true, map[string]interface{}{
			"laboratoryId": labID, "receivedAt": fmtTime(receivedAt),
		})
		s.emit("sample.received", "sample", sample.ID, map[string]interface{}{
			"sampleId": sample.ID, "laboratoryId": labID,
		})
		return 201, J{
			"sampleId": sample.ID, "status": "received",
			"receivedAt": fmtTime(receivedAt), "laboratoryId": labID,
		}, nil
	})
}

func (s *Service) hRecordLabException(c *opCtx) (int, interface{}, *ApiError) {
	if err := c.requireRole(RoleLaboratoryTeam); err != nil {
		return 0, nil, err
	}
	if err := checkFields(c.body, "sampleId", "laboratoryId", "reason", "occurredAt", "idempotencyKey"); err != nil {
		return 0, nil, err
	}
	return s.runIdempotent(c, "record_laboratory_exception", true, func() (int, interface{}, *ApiError) {
		sampleID, err := reqStr(c.body, "sampleId")
		if err != nil {
			return 0, nil, err
		}
		labID, err := reqStr(c.body, "laboratoryId")
		if err != nil {
			return 0, nil, err
		}
		reason, err := reqStr(c.body, "reason")
		if err != nil {
			return 0, nil, err
		}
		occurredAt, aerr := reqTimeField(c.body, "occurredAt")
		if aerr != nil {
			return 0, nil, aerr
		}
		sample := s.state.Samples[sampleID]
		if sample == nil {
			return 0, nil, apiErr(404, "not_found", "sample not found")
		}
		lab := s.state.Locations[labID]
		if lab == nil || lab.Implicit || !lab.HasFunction(LocLaboratory) {
			return 0, nil, apiErr(404, "not_found", "laboratory not found")
		}
		if c.user.AssignedLocationID != labID {
			return 0, nil, apiErr(403, "wrong_laboratory_operator", "you are not assigned to this laboratory")
		}
		if sample.Status == SampleReceived || sample.Status == SampleCancelled || sample.Status == SampleExpired {
			return 0, nil, apiErr(409, "invalid_sample_state", "sample is in a terminal state")
		}
		sample.Status = SampleException
		sample.Exception = &ExceptionInfo{
			Code: "laboratory_exception", Reason: reason, OccurredAt: occurredAt,
		}
		c.audit("record_laboratory_exception", "sample", sample.ID, sample.ID, true, map[string]interface{}{
			"laboratoryId": labID, "reason": reason,
		})
		s.emit("sample.exception", "sample", sample.ID, map[string]interface{}{
			"sampleId": sample.ID, "code": "laboratory_exception", "reason": reason,
		})
		return 201, J{"sampleId": sample.ID, "status": "exception", "exceptionReason": reason}, nil
	})
}
"}

{"command":"create","path":"/workspace/backend/ops_dispatch.go","file_text":"package main

import (
