		if !ok || n != float64(int(n)) || int(n) < 0 {
			return 0, nil, apiErr(400, "invalid_offset", "offset must be a non-negative integer")
		}
		f.Offset = int(n)
	}
	if v, ok := c.body["order"]; ok && v != nil {
		ord, ok := v.(string)
		if !ok || (ord != "newest_first" && ord != "oldest_first") {
			return 0, nil, apiErr(400, "invalid_order", "order must be newest_first or oldest_first")
		}
		f.NewestFirst = ord == "newest_first"
	}
	rows, total, err := s.store.SearchAudit(f)
	if err != nil {
		return 0, nil, apiErr(500, "internal_error", "audit search failed")
	}
	items := []J{}
	for _, r := range rows {
		items = append(items, auditView(r))
	}
	hasMore := f.Offset+len(rows) < total
	resp := J{"items": items, "hasMore": hasMore}
	if hasMore {
		resp["nextOffset"] = f.Offset + len(rows)
	} else {
		resp["nextOffset"] = nil
	}
	return 200, resp, nil
}
