func matchRoute(pattern, path string) (string, bool) {
	pp := strings.Split(strings.Trim(pattern, "/"), "/")
	sp := strings.Split(strings.Trim(path, "/"), "/")
	if len(pp) != len(sp) {
		return "", false
	}
	param := ""
	for i := range pp {
		if strings.HasPrefix(pp[i], "{") && strings.HasSuffix(pp[i], "}") {
			param = sp[i]
			continue
		}
		if pp[i] != sp[i] {
			return "", false
		}
	}
	return param, true
}

func (s *Service) ServeAPI(w http.ResponseWriter, r *http.Request) {
	path := r.URL.Path
	// WebSocket upgrades are handled outside the service lock
	if strings.ToLower(r.Header.Get("Upgrade")) == "websocket" {
		if path == "/api/events" {
			s.serveEventsWS(w, r)
		} else {
			writeErr(w, apiErr(404, "not_found", "resource not found"))
		}
		return
	}
	pathMatched := false
	for _, rt := range s.routes() {
		pathID, ok := matchRoute(rt.path, path)
		if !ok {
			continue
		}
		pathMatched = true
		if rt.method == r.Method {
			s.serveRoute(w, r, rt, pathID)
			return
		}
	}
	if pathMatched {
		writeErr(w, apiErr(405, "method_not_allowed", "method not allowed"))
		return
	}
	writeErr(w, apiErr(404, "not_found", "resource not found"))
}

