// wsToken extracts the session token from the Sec-WebSocket-Protocol header.
// Clients authenticate by offering a "bearer.<base64url(token)>" subprotocol.
func wsToken(r *http.Request) string {
	for _, hdr := range r.Header.Values("Sec-WebSocket-Protocol") {
		for _, p := range strings.Split(hdr, ",") {
			p = strings.TrimSpace(p)
			if !strings.HasPrefix(p, "bearer.") {
				continue
			}
			enc := strings.TrimPrefix(p, "bearer.")
			if raw, err := base64.RawURLEncoding.DecodeString(enc); err == nil {
				return string(raw)
			}
			if raw, err := base64.URLEncoding.DecodeString(enc); err == nil {
				return string(raw)
			}
		}
	}
	return ""
}

func (s *Service) serveEventsWS(w http.ResponseWriter, r *http.Request) {
	token := wsToken(r)
	if token == "" {
		token = strings.TrimSpace(strings.TrimPrefix(r.Header.Get("Authorization"), "Bearer "))
	}
	if token == "" {
		token = r.URL.Query().Get("token")
	}
	since := int64(0)
	if v := r.URL.Query().Get("since"); v != "" {
		if n, err := strconv.ParseInt(v, 10, 64); err == nil && n > 0 {
			since = n
		}
	}
	s.mu.Lock()
	sess := s.state.Sessions[token]
	s.mu.Unlock()
	if sess == nil {
		writeErr(w, apiErr(401, "unauthorized", "invalid token"))
		return
	}
	s.hub.ServeWS(w, r, since, s.store)
}

func (h *WSHub) ServeWS(w http.ResponseWriter, r *http.Request, since int64, store *Store) {
	conn, err := wsUpgrader.Upgrade(w, r, nil)
	if err != nil {
		return
	}
	// replay missed events since the cursor before going live
	if store != nil {
		if rows, err := store.EventsSince(since, 500); err == nil {
			for _, e := range rows {
				msg, _ := json.Marshal(J{
					"id": e.ID, "type": e.Type, "entityType": e.EntityType, "entityId": e.EntityID,
					"payload": json.RawMessage(e.Payload), "createdAt": fmtTime(e.CreatedAt),
				})
				conn.SetWriteDeadline(time.Now().Add(5 * time.Second))
				if err := conn.WriteMessage(websocket.TextMessage, msg); err != nil {
					conn.Close()
					return
				}
			}
		}
	}"}

