import json,re
ops=json.load(open('/tmp/ops.json'))
src={}
for f in ['handlers.go','ops_admin.go','ops_request.go','ops_work.go','ops_dispatch.go','service.go','main.go']:
    src[f]=open(f).read()
# map handler func name -> (file, body) via simple regex on func definition
funcs={}
for f,s in src.items():
    for m in re.finditer(r'func \(s \*Service\) (h\w+)\(', s):
        name=m.group(1)
        start=m.start()
        # find matching closing brace at column 0: next "\n}" 
        end=s.find('\n}\n',start)
        body=s[start:end if end!=-1 else len(s)]
        funcs[name]=(f,body)
routes=re.findall(r'\{"(POST|GET)", "(/api/[^"]+)", s\.(h\w+), (true|false)\}', src['handlers.go'])
rmap={path.replace('{id}','{sampleId}').replace('{userId}','{sampleId}'):h for meth,path,h,auth in routes}
issues=[]
for o in ops:
    path=o['path']
    if path in ('/ready','/api/events'): continue
    # normalize
    key=path
    h=rmap.get(key) or rmap.get(path.replace('{sampleId}','{id}')) or rmap.get(path.replace('{userId}','{id}'))
    if not h:
        issues.append((path,'NO HANDLER',None)); continue
    f,body=funcs[h]
    # checkFields allowed set
    cf=re.search(r'checkFields\(c\.body,([^)]*)\)', body)
    allowed=set(re.findall(r'"(\w+)"', cf.group(1))) if cf else set()
    allowed.discard('idempotencyKey')
    cprops=set(o['props'].keys())
    extra=allowed-cprops
    missing=cprops-allowed
    # error codes used
    codes=set(re.findall(r'apiErr\(\d+, "(\w+)"', body))
    cenum=set()
    for c,e in o['errs'].items():
        if e: cenum|=set(e)
    bad=codes-cenum-{'role_not_selected','concurrent_conflict','state_snapshot_changed','internal_error','unauthorized','forbidden'}
    if extra or missing or bad:
        issues.append((path,h,f'extra={extra} missing={missing} badcodes={bad}'))
for i in issues: print(i)
print(len(issues),'ops with issues')
EOF","summary":"Cross-check handlers vs contract fields and error codes"}

