{"command":"cd /workspace && python3 - <<'EOF'
import json,re,glob
c=json.load(open('contracts/openapi.contract.json'))
code=''
for f in glob.glob('backend/*.go'): code+=open(f).read()
for path,item in c['paths'].items():
    for method,op in item.items():
        body=op.get('requestBody',{}).get('content',{}).get('application/json',{}).get('schema')
        props=set((body or {}).get('properties',{}).keys())
        props.discard('idempotencyKey')
        m=re.search(r'func \(s \*Service\) (h\w+)\(c \*opCtx\).*?\n}\n', code, re.S)
        # find handler for this path via routes table
        rm=re.search(r'"%s", s\.(h\w+)'%re.escape(path), code)
        if not rm:
            print('NO ROUTE', path); continue
        fname=rm.group(1)
        fm=re.search(r'func \(s \*Service\) %s\(c \*opCtx\).*?\n}\n' % fname, code, re.S)
        seg=fm.group(0)
        # may delegate; also include called funcs
        for sub in re.findall(r's\.(h\w+|createRequestCommon|parseOriginSpec)\(', seg):
            sm=re.search(r'func \(s \*Service\) %s\(.*?\n}\n' % sub, code, re.S) or re.search(r'func %s\(.*?\n}\n' % sub, code, re.S)
            if sm: seg+=sm.group(0)
        if props:
            cf=re.search(r'checkFields\(c\.body, (.*?)\)', seg, re.S)
            allowed=set(re.findall(r'"(\w+)"', cf.group(1))) if cf else set()
            allowed.discard('idempotencyKey')
            if allowed and (props-allowed or allowed-props):
                print('FIELDS', path, 'missing=',props-allowed,'extra=',allowed-props)
        # error codes
        enum=set()
        for r in op['responses'].values():
            try: enum|=set(r['content']['application/json']['schema']['properties']['code']['enum'])
            except: pass
        if enum:
            used=set(re.findall(r'apiErr\(\d+, "(\w+)"', seg))
            # include helper-called funcs roughly
            bad=used-enum
            if bad: print('BADCODES', path, bad)
EOF","summary":"Rescan handlers vs contract fields and codes"}

