{"command":"create","path":"/workspace/frontend/src/api.ts","file_text":"export interface ApiError {
  status: number;
  code: string;
  message: string;
}

let token: string | null = localStorage.getItem('sessionToken');

export function setToken(t: string | null) {
  token = t;
  if (t) localStorage.setItem('sessionToken', t);
  else localStorage.removeItem('sessionToken');
}

export function getToken() {
  return token;
}

async function request(method: string, path: string, body?: unknown): Promise<any> {
  const headers: Record<string, string> = {};
  if (body !== undefined) headers['Content-Type'] = 'application/json';
  if (token) headers['Authorization'] = `Bearer ${token}`;
  const res = await fetch(path, {
    method,
    headers,
    body: body !== undefined ? JSON.stringify(body) : undefined,
  });
  let json: any = null;
  try {
    json = await res.json();
  } catch {
    /* no body */
  }
  if (!res.ok) {
    const err: ApiError = {
      status: res.status,
      code: json?.code ?? 'error',
      message: json?.error ?? `Request failed with status ${res.status}`,
    };
    throw err;
  }
  return json?.data !== undefined ? json.data : json;
}

export const api = {
  get: (path: string) => request('GET', path),
  post: (path: string, body?: unknown) => request('POST', path, body ?? {}),
};

export function uuid(): string {
  if (crypto.randomUUID) return crypto.randomUUID();
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0;
    return (c === 'x' ? r : (r & 0x3) | 0x8).toString(16);
  });
}

export function nowIso(): string {
  return new Date().toISOString();
}
"}

