{"command":"create","path":"/workspace/frontend/src/App.tsx","file_text":"import React, { createContext, useCallback, useContext, useEffect, useState } from 'react';
import { Link, Navigate, NavLink, Route, Routes, useNavigate } from 'react-router-dom';
import { api, getToken, setToken } from './api';
import { Role, ROLE_LABELS, SessionUser } from './types';
import LoginPage from './pages/Login';
import WorkPage from './pages/Work';
import SampleDetailPage from './pages/SampleDetail';
import NewRequestPage from './pages/NewRequest';
import MonitorPage from './pages/Monitor';
import AuditPage from './pages/Audit';
import AdminPage from './pages/Admin';

interface AuthCtx {
  user: SessionUser | null;
  loading: boolean;
  login: (username: string, password: string) => Promise<void>;
  logout: () => Promise<void>;
  selectRole: (role: Role) => Promise<void>;
  refresh: () => Promise<void>;
}

const Ctx = createContext<AuthCtx>(null as unknown as AuthCtx);
export const useAuth = () => useContext(Ctx);

export default function App() {
  const [user, setUser] = useState<SessionUser | null>(null);
  const [loading, setLoading] = useState(true);

  const refresh = useCallback(async () => {
    if (!getToken()) {
      setUser(null);
      setLoading(false);
      return;
    }
    try {
      const boot = await api.get('/api/ui/bootstrap');
      setUser(boot.user);
    } catch {
      setToken(null);
      setUser(null);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    refresh();
  }, [refresh]);

  const login = useCallback(async (username: string, password: string) => {
    const res = await api.post('/api/authenticate-user', { username, password });
    setToken(res.sessionToken);
    const boot = await api.get('/api/ui/bootstrap');
    setUser(boot.user);
  }, []);

  const logout = useCallback(async () => {
    try {
      await api.post('/api/sign-out-user', {});
    } catch {
      /* ignore */
    }
    setToken(null);
    setUser(null);
  }, []);

  const selectRole = useCallback(async (role: Role) => {
    const res = await api.post('/api/select-active-role', { role });
    setUser((u) => (u ? { ...u, activeRole: res.activeRole, roleSelectionRequired: false } : u));
  }, []);

  const ctx: AuthCtx = { user, loading, login, logout, selectRole, refresh };

  if (loading) {
    return <div className="container"><p>Loading…</p></div>;
  }
  if (!user) {
    return (
      <Ctx.Provider value={ctx}>
        <LoginPage />
      </Ctx.Provider>
    );
  }
  if (!user.activeRole) {
    return (
      <Ctx.Provider value={ctx}>
        <RoleSelectionScreen />
      </Ctx.Provider>
    );
  }
  return (
    <Ctx.Provider value={ctx}>
      <Shell />
    </Ctx.Provider>
  );
}

function RoleSelectionScreen() {
  const { user, selectRole, logout } = useAuth();
  const [error, setError] = useState('');
  if (!user) return null;
  return (
    <div className="container" style={{ maxWidth: 520 }}>
      <div className="card">
        <h2>Select your working role</h2>
        <p className="muted">
          Your account holds multiple roles. Choose the role you want to work under now; this only
          changes your current context and does not change your assigned roles.
        </p>
        {error && <div className="alert error" role="alert">{error}</div>}
        <fieldset style={{ border: 'none', padding: 0, margin: 0 }}>
          <legend className="muted">Available roles</legend>
          {user.roles.map((r) => (
            <div key={r} style={{ margin: '6px 0' }}>
              <label style={{ display: 'inline', fontWeight: 400 }}>
                <input
                  type="radio"
                  name="active-role"
                  value={r}
                  onChange={() =>
                    selectRole(r).catch((e) => setError(e.message ?? 'Could not select role'))
                  }
                />{' '}
                {ROLE_LABELS[r] ?? r}
              </label>
            </div>
          ))}
        </fieldset>
        <div className="actions">
          <button onClick={() => logout()}>Sign out</button>
        </div>
      </div>
    </div>
  );
}

function Shell() {
  const { user, logout, selectRole } = useAuth();
  const navigate = useNavigate();
  const [switchMsg, setSwitchMsg] = useState('');
  if (!user) return null;
  const role = user.activeRole as Role;
  const canMonitor = role === 'dispatcher' || role === 'administrator';
  const canAdmin = role === 'administrator';
  const canRequest = role === 'requester';

  return (
    <div>
      <header className="topbar">
        <h1>Lab Sample Pickup &amp; Delivery</h1>
        <nav aria-label="Main navigation">
          <NavLink to="/" end>My work</NavLink>
          {canRequest && <NavLink to="/request">New request</NavLink>}
          {canMonitor && <NavLink to="/monitor">Monitor</NavLink>}
          {canMonitor && <NavLink to="/audit">Audit</NavLink>}
          {canAdmin && <NavLink to="/admin">Administration</NavLink>}
        </nav>
        <span className="who">{user.fullName || user.username}</span>
        <label htmlFor="role-switch" style={{ margin: 0, color: '#cdd6f4', fontWeight: 400 }}>
          Active role
        </label>
        <select
          id="role-switch"
          aria-label="Active role"
          value={role}
          onChange={async (e) => {
            const r = e.target.value as Role;
            try {
              await selectRole(r);
              setSwitchMsg(`Now working as ${ROLE_LABELS[r] ?? r}`);
              navigate('/');
            } catch (err: any) {
              setSwitchMsg(err.message ?? 'Role switch failed');
            }
          }}
        >
          {user.roles.map((r) => (
            <option key={r} value={r}>
              {ROLE_LABELS[r] ?? r}
            </option>
          ))}
        </select>
        <button
          onClick={async () => {
            await logout();
            navigate('/');
          }}
        >
          Sign out
        </button>
      </header>
      {switchMsg && (
        <div className="container" style={{ marginBottom: -8 }}>
          <div className="alert info" role="status">{switchMsg}</div>
        </div>
      )}
      <main className="container">
        <Routes>
          <Route path="/" element={<WorkPage />} />
          <Route path="/samples/:id" element={<SampleDetailPage />} />
          <Route path="/request" element={canRequest ? <NewRequestPage /> : <Navigate to="/" />} />
          <Route path="/monitor" element={canMonitor ? <MonitorPage /> : <Navigate to="/" />} />
          <Route path="/audit" element={canMonitor ? <AuditPage /> : <Navigate to="/" />} />
          <Route path="/admin" element={canAdmin ? <AdminPage /> : <Navigate to="/" />} />
          <Route path="*" element={<Navigate to="/" />} />
        </Routes>
      </main>
    </div>
  );
}
"}

