              <strong>{entryStatus(e)}</strong>
              {e.role ? <span className="muted"> · {String(e.role)}</span> : null}
            </div>
            <div className="t-time">{entryTime(e)}</div>
          </li>
        ))}
      </ol>
    </div>
  );
}
