{"command":"create","path":"/workspace/frontend/src/pages/SampleDetail.tsx","file_text":"import React, { useCallback, useEffect, useState } from 'react';
import { useParams } from 'react-router-dom';
import { api, nowIso, uuid } from '../api';
import { useAuth } from '../App';
import Timeline from '../components/Timeline';
import MapView from '../components/MapView';
import { JourneyPlan, SampleLifecycle, SampleState } from '../types';

export default function SampleDetailPage() {
  const { id } = useParams<{ id: string }>();
  const { user } = useAuth();
  const [state, setState] = useState<SampleState | null>(null);
  const [lifecycle, setLifecycle] = useState<SampleLifecycle | null>(null);
  const [plan, setPlan] = useState<JourneyPlan | null>(null);
  const [error, setError] = useState('');
  const [notice, setNotice] = useState('');

  const load = useCallback(async () => {
    if (!id) return;
    try {
      const st = await api.post('/api/read-sample-state', { sampleId: id });
      setState(st);
      const lc = await api.post('/api/read-sample-lifecycle', { sampleId: id });
      setLifecycle(lc);
      const journeyId = st.activeJourneyId ?? lc.activeJourneyId;
      if (journeyId) {
        try {
          const jp = await api.post('/api/read-journey-plan', { journeyId });
          setPlan(jp);
        } catch {
          setPlan(null);
        }
      } else {
        setPlan(null);
      }
      setError('');
    } catch (e: any) {
      setError(e.message ?? 'Could not load sample');
    }
  }, [id]);

  useEffect(() => {
    load();
  }, [load]);

  if (error) {
    return <div className="alert error" role="alert">{error}</div>;
  }
  if (!state || !lifecycle) {
    return <p className="muted">Loading…</p>;
  }
  const status = state.state?.status ?? lifecycle.status;
  const isException = status === 'exception' || status === 'expired' || !!lifecycle.exception;
  const isOwner = user?.userId === state.requesterId;
  const canConfirmHandoff =
    lifecycle.pendingHandoffId &&
    user &&
    (lifecycle.pendingHandoff?.senderId === user.userId ||
      lifecycle.pendingHandoff?.receiverId === user.userId);

  const confirmHandoff = async (side: 'sender' | 'receiver') => {
    setNotice('');
    try {
      await api.post('/api/confirm-handoff', {
        handoffId: lifecycle.pendingHandoffId,
        confirmationSide: side,
        confirmedAt: nowIso(),
        idempotencyKey: uuid(),
      });
      setNotice('Handoff confirmed');
      await load();
    } catch (e: any) {
      setError(e.message ?? 'Could not confirm handoff');
    }
  };

  return (
    <div>
      <h2>
        Sample {state.sampleId}{' '}
        <span className={`badge ${isException ? 'exception' : ''}`}>{status}</span>
      </h2>
      {notice && <div className="alert ok" role="status">{notice}</div>}
      {isException && (
        <div className="alert error" role="alert" aria-label="Exception">
          <strong>Exception:</strong>{' '}
          {lifecycle.exception?.code ?? status}
          {lifecycle.exception?.reason ? ` — ${lifecycle.exception.reason}` : ''}
        </div>
      )}
      <div className="grid2">
        <div className="card">
          <h2>Tracking</h2>
          <dl className="kv">
            <dt>Current status</dt>
            <dd>{status}</dd>
            <dt>Current custodian</dt>
            <dd>{lifecycle.currentHolderId ?? state.currentHolderId ?? '—'}</dd>
            <dt>Current / last known location</dt>
            <dd>
              {state.latestLocation ?? lifecycle.latestLocation
                ? `${(state.latestLocation ?? lifecycle.latestLocation)!.latitude.toFixed(5)}, ${(state.latestLocation ?? lifecycle.latestLocation)!.longitude.toFixed(5)}`
                : 'No location recorded yet'}
            </dd>
            <dt>Last update</dt>
            <dd>
              {state.locationRecordedAt ?? lifecycle.locationRecordedAt
                ? new Date(String(state.locationRecordedAt ?? lifecycle.locationRecordedAt)).toLocaleString()
                : '—'}
            </dd>
            <dt>Location freshness</dt>
            <dd>
              <span className={`badge ${lifecycle.locationStale ? 'stale' : 'fresh'}`}>
                {lifecycle.locationStale ? 'stale' : 'fresh'}
              </span>
              {isOwner && <span className="muted"> (visible to you as the request owner)</span>}
            </dd>
            <dt>Delivery deadline</dt>
            <dd>{state.deliveryDeadline ? new Date(state.deliveryDeadline).toLocaleString() : '—'}</dd>
            <dt>Sealed</dt>
            <dd>{lifecycle.sealed ? 'yes' : 'no'}</dd>
            <dt>Route progress</dt>
            <dd>
              {plan
                ? `${lifecycle.completedLegIds.length} of ${plan.legs?.length ?? lifecycle.completedLegIds.length} legs completed`
                : `${lifecycle.completedLegIds.length} legs completed`}
            </dd>
          </dl>
          {canConfirmHandoff && (
            <div className="actions">
              {lifecycle.pendingHandoff?.senderId === user!.userId && (
                <button className="primary" onClick={() => confirmHandoff('sender')}>
                  Confirm handoff as sender
                </button>
              )}
              {lifecycle.pendingHandoff?.receiverId === user!.userId && (
                <button className="primary" onClick={() => confirmHandoff('receiver')}>
                  Confirm handoff as receiver
                </button>
              )}
            </div>
          )}
        </div>
        <div className="card">
          <h2>Map</h2>
          <MapView
            markers={[
              ...(state.origin
                ? [{ id: 'origin', lat: state.origin.latitude, lng: state.origin.longitude, label: 'Origin', color: '#1d4ed8' }]
                : []),
              ...((state.latestLocation ?? lifecycle.latestLocation)
                ? [{
                    id: 'current',
                    lat: (state.latestLocation ?? lifecycle.latestLocation)!.latitude,
                    lng: (state.latestLocation ?? lifecycle.latestLocation)!.longitude,
                    label: 'Last known location',
                    color: '#b91c1c',
                  }]
                : []),
            ]}
          />
        </div>
      </div>
      <div className="card">
        <h2>Status history</h2>
        <Timeline entries={lifecycle.timeline ?? state.timeline ?? []} label="Ordered status history" />
      </div>
      {plan && (
        <div className="card">
          <h2>Journey plan</h2>
          <dl className="kv">
            <dt>Journey</dt>
            <dd>{plan.journeyId}</dd>
            <dt>Status</dt>
            <dd>{plan.status}</dd>
            <dt>Plan version</dt>
            <dd>{plan.planVersion}</dd>
            <dt>Route mode</dt>
            <dd>{plan.routeMode ?? '—'}</dd>
            <dt>Estimated delivery</dt>
            <dd>{plan.estimatedDeliveryAt ? new Date(plan.estimatedDeliveryAt).toLocaleString() : '—'}</dd>
          </dl>
          {plan.legs && plan.legs.length > 0 && (
            <table aria-label="Journey legs">
              <thead>
                <tr>
                  <th>#</th>
                  <th>Leg</th>
                  <th>From</th>
                  <th>To</th>
                  <th>Status</th>
                </tr>
              </thead>
              <tbody>
                {plan.legs.map((leg: any, i: number) => (
                  <tr key={leg.assignmentId ?? i}>
                    <td>{i + 1}</td>
                    <td>{leg.kind ?? leg.assignmentId}</td>
                    <td>{leg.fromLocationId ?? '—'}</td>
                    <td>{leg.toLocationId ?? leg.nodeId ?? leg.laboratoryId ?? '—'}</td>
                    <td>{leg.status}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      )}
    </div>
  );
}
"}

{"command":"create","path":"/workspace/frontend/src/components/MapView.tsx","file_text":"import React, { useEffect, useRef } from 'react';
import maplibregl from 'maplibre-gl';
import { Protocol } from 'pmtiles';

let protocolRegistered = false;
function registerProtocol() {
  if (!protocolRegistered) {
    const protocol = new Protocol();
    maplibregl.addProtocol('pmtiles', protocol.tile);
    protocolRegistered = true;
  }
}

export interface MapMarker {
  id: string;
  lat: number;
  lng: number;
  label?: string;
  color?: string;
}

export default function MapView({
  markers = [],
  height,
}: {
  markers?: MapMarker[];
  height?: number;
}) {
  const ref = useRef<HTMLDivElement>(null);
  const mapRef = useRef<maplibregl.Map | null>(null);
  const markersRef = useRef<maplibregl.Marker[]>([]);

  useEffect(() => {
    registerProtocol();
    if (!ref.current || mapRef.current) return;
    const map = new maplibregl.Map({
      container: ref.current,
      style: '/map-assets/style.json',
      center: [77.5946, 12.9716],
      zoom: 11,
      attributionControl: { compact: true },
    });
    map.addControl(new maplibregl.NavigationControl(), 'top-right');
    mapRef.current = map;
    return () => {
      map.remove();
      mapRef.current = null;
    };
  }, []);

  useEffect(() => {
    const map = mapRef.current;
    if (!map) return;
    markersRef.current.forEach((m) => m.remove());
    markersRef.current = markers.map((mk) => {
      const el = document.createElement('div');
      el.style.width = '14px';
      el.style.height = '14px';
      el.style.borderRadius = '50%';
      el.style.background = mk.color ?? '#1d4ed8';
      el.style.border = '2px solid #fff';
      const marker = new maplibregl.Marker({ element: el })
        .setLngLat([mk.lng, mk.lat])
        .addTo(map);
      if (mk.label) {
        marker.setPopup(new maplibregl.Popup({ offset: 12 }).setText(mk.label));
      }
      return marker;
    });
    if (markers.length > 0) {
      const bounds = new maplibregl.LngLatBounds();
      markers.forEach((m) => bounds.extend([m.lng, m.lat]));
      if (markers.length === 1) {
        map.easeTo({ center: [markers[0].lng, markers[0].lat], zoom: 12 });
      } else {
        map.fitBounds(bounds, { padding: 60, maxZoom: 13 });
      }
    }
  }, [markers]);

  return (
    <div
      ref={ref}
      className={`map-wrap${height && height < 300 ? ' small' : ''}`}
      style={height ? { height } : undefined}
      role="region"
      aria-label="Map"
    />
  );
}
"}

