        containerType,
        temperatureMinC: parseFloat(tempMin),
        temperatureMaxC: parseFloat(tempMax),
        incompatibleSampleTypes: [],
        idempotencyKey: uuid(),
      });
      navigate(`/samples/${res.sampleId}`);
    } catch (err: any) {
      setError(err.message ?? 'Could not register sample');
    } finally {
