{"command":"create","path":"/workspace/frontend/src/pages/Audit.tsx","file_text":"import React, { useState } from 'react';
import { api } from '../api';
import { AuditEntry } from '../types';

export default function AuditPage() {
  const [query, setQuery] = useState('');
  const [entityType, setEntityType] = useState('');
  const [entityId, setEntityId] = useState('');
  const [action, setAction] = useState('');
  const [actorId, setActorId] = useState('');
  const [order, setOrder] = useState('newest_first');
  const [result, setResult] = useState<{ entries: AuditEntry[]; total: number; hasMore: boolean; nextOffset?: number } | null>(null);
  const [error, setError] = useState('');
  const [offset, setOffset] = useState(0);

  const search = async (off: number) => {
    setError('');
    try {
      const res = await api.post('/api/search-audit-trail', {
        query,
        actorId,
        entityType,
        entityId,
        action,
        role: '',
        fromTime: '',
        toTime: '',
        limit: 50,
        offset: off,
        order,
      });
      setResult(res);
      setOffset(off);
    } catch (e: any) {
      setError(e.message ?? 'Audit search failed');
    }
  };

  return (
    <div>
      <h2>Audit trail</h2>
      {error && <div className="alert error" role="alert">{error}</div>}
      <div className="card">
        <form
          onSubmit={(e) => {
            e.preventDefault();
            search(0);
          }}
        >
          <div className="field-row">
            <div>
              <label htmlFor="q">Search text</label>
              <input id="q" value={query} onChange={(e) => setQuery(e.target.value)} />
            </div>
            <div>
              <label htmlFor="aAction">Action</label>
              <input id="aAction" value={action} onChange={(e) => setAction(e.target.value)} />
            </div>
          </div>
          <div className="field-row">
            <div>
              <label htmlFor="aEntityType">Entity type</label>
              <input
                id="aEntityType"
                value={entityType}
                onChange={(e) => setEntityType(e.target.value)}
                placeholder="sample, request, journey…"
              />
            </div>
            <div>
              <label htmlFor="aEntityId">Entity ID</label>
              <input id="aEntityId" value={entityId} onChange={(e) => setEntityId(e.target.value)} />
            </div>
          </div>
          <div className="field-row">
            <div>
              <label htmlFor="aActor">Actor ID</label>
              <input id="aActor" value={actorId} onChange={(e) => setActorId(e.target.value)} />
            </div>
            <div>
              <label htmlFor="aOrder">Order</label>
              <select id="aOrder" value={order} onChange={(e) => setOrder(e.target.value)}>
                <option value="newest_first">Newest first</option>
                <option value="oldest_first">Oldest first</option>
              </select>
            </div>
          </div>
          <div className="actions">
            <button className="primary" type="submit">
              Search audit trail
            </button>
          </div>
        </form>
      </div>
      {result && (
        <div className="card">
          <p className="muted">
            {result.total} record{result.total === 1 ? '' : 's'} found
          </p>
          <table aria-label="Audit entries">
            <thead>
              <tr>
                <th>Time</th>
                <th>Actor</th>
                <th>Role</th>
                <th>Action</th>
                <th>Entity</th>
                <th>Outcome</th>
                <th>Details</th>
              </tr>
            </thead>
            <tbody>
              {result.entries.map((e) => (
                <tr key={e.auditId}>
                  <td>{e.occurredAt ? new Date(e.occurredAt).toLocaleString() : ''}</td>
                  <td>{e.actorId}</td>
                  <td>{e.role}</td>
                  <td>{e.action}</td>
                  <td>
                    {e.entityType} {e.entityId}
                  </td>
                  <td>{e.success ? 'success' : 'failure'}</td>
                  <td>
                    <code style={{ fontSize: 11 }}>
                      {e.details ? JSON.stringify(e.details).slice(0, 120) : ''}
                    </code>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          <div className="actions">
            {offset > 0 && (
              <button onClick={() => search(Math.max(0, offset - 50))}>Previous page</button>
            )}
            {result.hasMore && result.nextOffset !== undefined && (
              <button onClick={() => search(result.nextOffset!)}>Next page</button>
            )}
          </div>
        </div>
      )}
    </div>
  );
}
"}

{"command":"create","path":"/workspace/frontend/src/pages/Admin.tsx","file_text":"import React, { useCallback, useEffect, useState } from 'react';
import { api } from '../api';
import CapacityTable from '../components/CapacityTable';
import { OperationsState, ROLE_LABELS, ServiceabilitySnapshot } from '../types';

const ALL_ROLES = Object.keys(ROLE_LABELS);
const FUNCTIONS = ['collection_point', 'transfer_point', 'hub', 'laboratory'];

export default function AdminPage() {
  const [ops, setOps] = useState<OperationsState | null>(null);
  const [snapshot, setSnapshot] = useState<ServiceabilitySnapshot | null>(null);
  const [error, setError] = useState('');
  const [notice, setNotice] = useState('');

  const load = useCallback(async () => {
    try {
      const res = await api.post('/api/read-operations-state', { filters: {} });
      setOps(res);
      const snap = await api.post('/api/read-serviceability-snapshot', {});
      setSnapshot(snap);
      setError('');
    } catch (e: any) {
      setError(e.message ?? 'Could not load admin data');
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  const run = async (fn: () => Promise<any>, okMsg: string) => {
    setNotice('');
    setError('');
    try {
      await fn();
      setNotice(okMsg);
      await load();
    } catch (e: any) {
      setError(e.message ?? 'Action failed');
    }
  };

  return (
    <div>
      <h2>Administration</h2>
      {error && <div className="alert error" role="alert">{error}</div>}
      {notice && <div className="alert ok" role="status">{notice}</div>}

      <details className="card" open>
        <summary><strong>Users</strong></summary>
        <CreateUserForm run={run} />
        <UpdateUserForm run={run} />
        <WorkerAvailabilityForm run={run} />
      </details>

      <details className="card">
        <summary><strong>Locations</strong></summary>
        <CreateLocationForm run={run} />
        <LocationStatusForm run={run} />
        <LocationFunctionForm run={run} />
        {ops && (
          <table aria-label="Existing locations">
            <thead>
              <tr>
                <th>ID</th>
                <th>Name</th>
                <th>Functions</th>
                <th>Active</th>
                <th>Capacity</th>
              </tr>
            </thead>
            <tbody>
              {(ops.locations ?? []).map((l) => (
                <tr key={l.locationId}>
                  <td><code>{l.locationId}</code></td>
                  <td>{l.name}</td>
                  <td>{(l.functions ?? []).join(', ')}</td>
                  <td>{l.active ? 'yes' : 'no'}</td>
                  <td>
                    {l.capacity
                      ? `regular ${l.capacity.availableUnits}/${l.capacity.capacityUnits}, cooled ${l.capacity.cooledAvailableUnits}/${l.capacity.cooledCapacityUnits}`
                      : '—'}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </details>

      <details className="card">
        <summary><strong>Connections</strong></summary>
        <CreateConnectionForm run={run} />
        <ConnectionStatusForm run={run} />
        {ops && (
          <table aria-label="Existing connections">
            <thead>
              <tr>
                <th>ID</th>
                <th>From</th>
                <th>To</th>
                <th>Travel (min)</th>
                <th>Cooled</th>
                <th>Active</th>
              </tr>
            </thead>
            <tbody>
              {(ops.connections ?? []).map((c) => (
                <tr key={c.connectionId}>
                  <td><code>{c.connectionId}</code></td>
                  <td>{c.fromLocationId}</td>
                  <td>{c.toLocationId}</td>
                  <td>{c.travelMinutes}</td>
                  <td>{c.cooled ? 'yes' : 'no'}</td>
                  <td>{c.active ? 'yes' : 'no'}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </details>

      <details className="card">
        <summary><strong>Sample types</strong></summary>
        <CreateSampleTypeForm run={run} />
        <UpdateSampleTypeForm run={run} />
      </details>

      <details className="card">
        <summary><strong>Capacity and laboratory acceptance</strong></summary>
        <CapacityForm run={run} />
        <LabAcceptanceForm run={run} />
      </details>

      <div className="card">
        <h2>Serviceability snapshot</h2>
        {snapshot ? (
          <>
            <dl className="kv">
              <dt>Version</dt>
              <dd>{snapshot.version}</dd>
              <dt>Status</dt>
              <dd>{snapshot.status}</dd>
              <dt>Computed at</dt>
              <dd>{snapshot.computedAt ? new Date(snapshot.computedAt).toLocaleString() : '—'}</dd>
              <dt>Network revision</dt>
              <dd>{snapshot.networkRevision}</dd>
              <dt>Active collection points</dt>
              <dd>{snapshot.activeCollectionPointCount}</dd>
            </dl>
            <table aria-label="Serviceability regions">
              <thead>
                <tr>
                  <th>Location</th>
                  <th>Name</th>
                  <th>Latitude</th>
                  <th>Longitude</th>
                  <th>Coverage (km)</th>
                </tr>
              </thead>
              <tbody>
                {(snapshot.regions ?? []).map((r) => (
                  <tr key={r.locationId}>
                    <td><code>{r.locationId}</code></td>
                    <td>{r.name}</td>
                    <td>{r.latitude}</td>
                    <td>{r.longitude}</td>
                    <td>{r.coverageKm}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </>
        ) : (
          <p className="muted">Loading…</p>
        )}
      </div>
    </div>
  );
}

type Run = (fn: () => Promise<any>, okMsg: string) => Promise<void>;

function TextField({ id, label, value, onChange, required }: {
  id: string; label: string; value: string; onChange: (v: string) => void; required?: boolean;
}) {
  return (
    <div>
      <label htmlFor={id}>{label}</label>
      <input id={id} value={value} onChange={(e) => onChange(e.target.value)} required={required} />
    </div>
  );
}

